--[[
	InventoryLayout/Metrics  -  the Inventory panel's sizes outside Classic, by the theme's text size
	(offsets at UI scale 1).
	  Metrics.get() -> the table for the current text size
	  Metrics.live() -> a table that reads Metrics.get() at each look-up, so what keeps it
	                    (refs.InvSkin.metrics, layout slots) follows a new text size without a rebuild
	The panel opens Columns x Rows tiles. InventoryWiring reads Tile, TileGap, TileName, TileCorner and
	TooltipLift through refs.InvSkin.metrics. TileName 0: tiles have no name line (the tooltip names them).
]]

local C = require(script.Parent.Parent.Constants)

local SIZES = {
	[12] = {
		Columns = 6, Rows = 6, MinWidth = 340, MinHeight = 300,
		Tile = 64, TileGap = 6, TileName = 0, TileCorner = 6, TooltipLift = 20,
		Title = 84, TabRow = 24, Circle = 24, SearchCount = 60,
		FilterMenu = 264, AddMenu = 200, MoreMenu = 200, MenuMax = 200,
		Preview = 88, FactLabel = 64, FactRow = 16, Copy = 44, ActionRow = 24, Favourite = 88,
	},
	[16] = {
		Columns = 6, Rows = 6, MinWidth = 400, MinHeight = 320,
		Tile = 64, TileGap = 6, TileName = 0, TileCorner = 6, TooltipLift = 20,
		Title = 104, TabRow = 28, Circle = 28, SearchCount = 64,
		FilterMenu = 328, AddMenu = 248, MoreMenu = 232, MenuMax = 220,
		Preview = 108, FactLabel = 84, FactRow = 20, Copy = 56, ActionRow = 32, Favourite = 112,
	},
}

local Metrics = {}

function Metrics.get()
	return SIZES[C.T.TextSize] or SIZES[16]
end

function Metrics.live()
	return setmetatable({}, {
		__index = function(_, key)
			return Metrics.get()[key]
		end,
	})
end

return Metrics
